253: function advanceYear() {
254:   if (state.dead) return toast('Esta vida chegou ao fim. Comece uma nova história.');
255:   state.age++; state.year++; const c = state.career;
256:   const wasInPrison = state.prisonYears > 0;
257:   if (wasInPrison) state.prisonYears = Math.max(0, state.prisonYears - 1);
258:   const income = c.employed && state.prisonYears === 0 && !wasInPrison ? c.salary * 12 : 0;
259:   const expenses = Math.round(state.finances.expenses * 12 * (1 + state.age / 500));
260:   const investmentReturn = state.finances.investments * ((Math.random() * .12) - .03);
261:   state.finances.investments = Math.max(0, state.finances.investments + investmentReturn);
262:   const balanceBeforeDebt = state.money + income - expenses;
263:   const deficit = Math.max(0, -balanceBeforeDebt);
264:   state.money = Math.max(0, balanceBeforeDebt);
265:   if (deficit) { state.finances.debt += deficit; state.credit = clamp(state.credit - 35, 0, 900); }
266:   else { state.finances.debt = Math.max(0, state.finances.debt - Math.min(state.finances.debt, income * .05)); state.credit = clamp(state.credit + 8, 0, 900); }
267:   const agePenalty = state.age > 70 ? 2.5 : state.age > 45 ? 1 : .25;
268:   state.health -= agePenalty + (state.stress > 70 ? 1.5 : 0);
269:   state.happiness += deficit ? -6 : state.money > expenses ? 1 : -1;
270:   state.stress = clamp(state.stress + 3 + (deficit ? 5 : 0) - (state.trait === 'espiritual' ? 2 : 0));
271:   state.energy = clamp(state.energy + (state.age < 30 ? 2 : -3));
272:   state.relationships.forEach(person => { person.affinity = clamp(person.affinity - (Math.random() < .4 ? 2 : 0)); });
273:   state.children.forEach(child => { child.age = safeNumber(child.age) + 1; });
274:   if (c.employed) {
275:     c.skill = clamp(c.skill + (state.education > 70 ? 4 : 2));
276:     if (Math.random() < .3 && c.level < 10) { c.level++; c.salary = Math.round(c.salary * 1.08); addEvent('↗', 'Uma promoção chegou', `Seu salário agora é ${money(c.salary)} por mês.`, 'blue'); }
277:   }
278:   if (state.age >= 45 && Math.random() < .08 && !state.healthConditions.includes('pressão alta')) state.healthConditions.push('pressão alta');
279:   const event = yearlyEvent(); addEvent(event.icon, event.title, event.text, event.cls);
280:   if (wasInPrison) addEvent('⚖', 'Um ano difícil', state.prisonYears ? `Você cumpriu mais um ano de prisão. Restam ${state.prisonYears}.` : 'Você cumpriu sua pena e está tentando reconstruir a vida.', 'pink');
281:   state.history.push({ year: state.year, age: state.age, money: Math.round(state.money), career: c.title });
282:   if (state.health <= 0 || (state.age >= 92 && Math.random() < .15) || state.age >= 105) {
283:     state.dead = true; addEvent('☾', 'O fim de uma jornada', 'Sua história terminou, mas seu legado permanece.', 'pink');
284:   }
285:   commit(`Ano ${state.year}: ${income >= expenses ? 'suas contas fecharam no azul' : 'suas despesas exigiram atenção'}`);
286: }
