258: function advanceYear() {
259:   if (state.dead) return toast('Esta vida chegou ao fim. Comece uma nova história.');
260:   state.age++; state.year++; const c = state.career;
261:   const wasInPrison = state.prisonYears > 0;
262:   if (wasInPrison) state.prisonYears = Math.max(0, state.prisonYears - 1);
263:   const income = c.employed && state.prisonYears === 0 && !wasInPrison ? c.salary * 12 : 0;
264:   const expenses = Math.round(state.finances.expenses * 12 * (1 + state.age / 500));
265:   const investmentReturn = state.finances.investments * ((Math.random() * .12) - .03);
266:   state.finances.investments = Math.max(0, state.finances.investments + investmentReturn);
267:   const balanceBeforeDebt = state.money + income - expenses;
268:   const deficit = Math.max(0, -balanceBeforeDebt);
269:   state.money = Math.max(0, balanceBeforeDebt);
270:   if (deficit) { state.finances.debt += deficit; state.credit = clamp(state.credit - 35, 0, 900); }
271:   else { state.finances.debt = Math.max(0, state.finances.debt - Math.min(state.finances.debt, income * .05)); state.credit = clamp(state.credit + 8, 0, 900); }
272:   const agePenalty = state.age > 70 ? 2.5 : state.age > 45 ? 1 : .25;
273:   state.health -= agePenalty + (state.stress > 70 ? 1.5 : 0);
274:   state.happiness += deficit ? -6 : state.money > expenses ? 1 : -1;
275:   state.stress = clamp(state.stress + 3 + (deficit ? 5 : 0) - (state.trait === 'espiritual' ? 2 : 0));
276:   state.energy = clamp(state.energy + (state.age < 30 ? 2 : -3));
277:   state.relationships.forEach(person => { person.affinity = clamp(person.affinity - (Math.random() < .4 ? 2 : 0)); });
278:   state.children.forEach(child => { child.age = safeNumber(child.age) + 1; });
279:   if (c.employed) {
280:     c.skill = clamp(c.skill + (state.education > 70 ? 4 : 2));
281:     c.satisfaction = clamp((c.satisfaction || 70) + (c.remote ? 1 : -1) - (state.stress > 70 ? 3 : 0));
282:     if (Math.random() < .3 && c.level < 10) { c.level++; c.salary = Math.round(c.salary * 1.08); addEvent('↗', 'Uma promoção chegou', `Seu salário agora é ${money(c.salary)} por mês.`, 'blue'); }
283:   }
284:   if (state.age >= 45 && Math.random() < .08 && !state.healthConditions.includes('pressão alta')) state.healthConditions.push('pressão alta');
285:   const event = yearlyEvent(); addEvent(event.icon, event.title, event.text, event.cls);
286:   if (wasInPrison) addEvent('⚖', 'Um ano difícil', state.prisonYears ? `Você cumpriu mais um ano de prisão. Restam ${state.prisonYears}.` : 'Você cumpriu sua pena e está tentando reconstruir a vida.', 'pink');
287:   state.history.push({ year: state.year, age: state.age, money: Math.round(state.money), career: c.title });
288:   if (state.health <= 0 || (state.age >= 92 && Math.random() < .15) || state.age >= 105) {
289:     state.dead = true; addEvent('☾', 'O fim de uma jornada', 'Sua história terminou, mas seu legado permanece.', 'pink');
290:   }
291:   commit(`Ano ${state.year}: ${income >= expenses ? 'suas contas fecharam no azul' : 'suas despesas exigiram atenção'}`);
292: }
