61:   cost = Math.max(0, safeNumber(cost)); energy = Math.max(0, safeNumber(energy));
62:   if (state.money < cost) { toast(`Você precisa de ${money(cost - state.money)} a mais.`); return false; }
63:   if (state.energy < energy) { toast('Você está sem energia para isso. Descanse ou avance um ano.'); return false; }
64:   state.money -= cost; state.energy = clamp(state.energy - energy); return true;
65: }
66: function requireEnergy(amount) {
67:   amount = Math.max(0, safeNumber(amount));
68:   if (state.energy < amount) { toast('Você está sem energia para isso. Descanse ou avance um ano.'); return false; }
69:   state.energy = clamp(state.energy - amount); return true;
70: }
71: function requireAge(minimum, message = `Você precisa ter pelo menos ${minimum} anos.`) {
72:   if (state.age < minimum) { toast(message); return false; }
73:   return true;
