75: function canAct(key, years = 1) {
76:   const until = safeNumber(state.cooldowns[key], 0);
77:   if (until > state.year) { toast(`Você poderá fazer isso novamente em ${until}.`); return false; }
78:   state.cooldowns[key] = state.year + years; return true;
