267: function advanceYear() {
268:   if (state.dead) return toast('Esta vida chegou ao fim. Comece uma nova história.');
269:   state.age++; state.year++; const c = state.career;
270:   const wasInPrison = state.prisonYears > 0;
271:   if (wasInPrison) state.prisonYears = Math.max(0, state.prisonYears - 1);
272:   const income = c.employed && state.prisonYears === 0 && !wasInPrison ? c.salary * 12 : 0;
273:   const expenses = Math.round(state.finances.expenses * 12 * (1 + state.age / 500));
274:   const investmentReturn = state.finances.investments * ((Math.random() * .12) - .03);
275:   state.finances.investments = Math.max(0, state.finances.investments + investmentReturn);
276:   const balanceBeforeDebt = state.money + income - expenses;
277:   const deficit = Math.max(0, -balanceBeforeDebt);
278:   state.money = Math.max(0, balanceBeforeDebt);
279:   if (deficit) { state.finances.debt += deficit; state.credit = clamp(state.credit - 35, 0, 900); }
280:   else { state.finances.debt = Math.max(0, state.finances.debt - Math.min(state.finances.debt, income * .05)); state.credit = clamp(state.credit + 8, 0, 900); }
281:   const agePenalty = state.age > 70 ? 2.5 : state.age > 45 ? 1 : .25;
282:   state.health = clamp(state.health - agePenalty - (state.stress > 70 ? 1.5 : 0));
283:   changeStat('happiness', deficit ? -6 : state.money > expenses ? 1 : -1);
284:   state.stress = clamp(state.stress + 3 + (deficit ? 5 : 0) - (state.trait === 'espiritual' ? 2 : 0));
285:   state.energy = clamp(state.energy + (state.age < 30 ? 2 : -3));
286:   state.relationships.forEach(person => { person.affinity = clamp(person.affinity - (Math.random() < .4 ? 2 : 0)); });
287:   state.children.forEach(child => { child.age = safeNumber(child.age) + 1; });
288:   if (c.employed) {
289:     c.skill = clamp(c.skill + (state.education > 70 ? 4 : 2));
290:     c.satisfaction = clamp((c.satisfaction || 70) + (c.remote ? 1 : -1) - (state.stress > 70 ? 3 : 0));
291:     if (Math.random() < .3 && c.level < 10) { c.level++; c.salary = Math.round(c.salary * 1.08); addEvent('↗', 'Uma promoção chegou', `Seu salário agora é ${money(c.salary)} por mês.`, 'blue'); }
292:   }
293:   if (state.age >= 45 && Math.random() < .08 && !state.healthConditions.includes('pressão alta')) state.healthConditions.push('pressão alta');
294:   const event = yearlyEvent(); addEvent(event.icon, event.title, event.text, event.cls);
295:   if (wasInPrison) addEvent('⚖', 'Um ano difícil', state.prisonYears ? `Você cumpriu mais um ano de prisão. Restam ${state.prisonYears}.` : 'Você cumpriu sua pena e está tentando reconstruir a vida.', 'pink');
296:   state.history.push({ year: state.year, age: state.age, money: Math.round(state.money), career: c.title });
297:   const reachedLimit = state.age >= 105;
298:   const healthFailure = state.health <= 0;
299:   const lateLifeRisk = state.age >= 92 && Math.random() < .15;
300:   if (healthFailure || lateLifeRisk || reachedLimit) {
301:     state.dead = true;
302:     state.deathCause = healthFailure ? 'complicações de saúde' : reachedLimit ? 'idade avançada' : 'fim natural da jornada';
303:     addEvent('☾', 'O fim de uma jornada', `Sua história terminou por ${state.deathCause}, mas seu legado permanece.`, 'pink');
304:   }
305:   commit(`Ano ${state.year}: ${income >= expenses ? 'suas contas fecharam no azul' : 'suas despesas exigiram atenção'}`);
306: }
