382:   state.age++; state.year++; const c = state.career;
383:   const wasInPrison = state.prisonYears > 0;
384:   if (wasInPrison) state.prisonYears = Math.max(0, state.prisonYears - 1);
385:   const income = c.employed && state.prisonYears === 0 && !wasInPrison ? c.salary * 12 : 0;
386:   const expenses = Math.round(state.finances.expenses * 12 * (1 + state.age / 500));
387:   const investmentReturn = state.finances.investments * ((Math.random() * .12) - .03);
388:   state.finances.investments = Math.max(0, state.finances.investments + investmentReturn);
389:   const balanceBeforeDebt = state.money + income - expenses;
390:   const deficit = Math.max(0, -balanceBeforeDebt);
391:   state.money = Math.max(0, balanceBeforeDebt);
392:   if (deficit) { state.finances.debt += deficit; state.credit = clamp(state.credit - 35, 0, 900); }
393:   else { state.finances.debt = Math.max(0, state.finances.debt - Math.min(state.finances.debt, income * .05)); state.credit = clamp(state.credit + 8, 0, 900); }
394:   const agePenalty = state.age > 70 ? 2.5 : state.age > 45 ? 1 : .25;
395:   state.health = clamp(state.health - agePenalty - (state.stress > 70 ? 1.5 : 0));
396:   changeStat('happiness', deficit ? -6 : state.money > expenses ? 1 : -1);
397:   state.stress = clamp(state.stress + 3 + (deficit ? 5 : 0) - (state.trait === 'espiritual' ? 2 : 0));
398:   state.energy = clamp(state.energy + (state.age < 30 ? 2 : -3));
399:   state.needs.sleep = clamp(state.needs.sleep - 5 + (state.energy > 60 ? 4 : 0));
400:   state.needs.social = clamp(state.needs.social - 3 + (state.relationships.length ? 2 : 0));
401:   state.needs.nutrition = clamp(state.needs.nutrition - 2 + (state.money > expenses ? 3 : 0));
402:   state.needs.purpose = clamp(state.needs.purpose + (c.employed ? 2 : -4));
403:   const neglectedNeeds = Object.values(state.needs).filter(value => value < 30).length;
404:   if (neglectedNeeds) { state.stress = clamp(state.stress + neglectedNeeds * 4); state.health = clamp(state.health - neglectedNeeds * 2); }
405:   state.relationships.forEach(person => { person.affinity = clamp(person.affinity - (Math.random() < .4 ? 2 : 0)); });
406:   state.children.forEach(child => { child.age = safeNumber(child.age) + 1; });
407:   if (c.employed) {
408:     c.skill = clamp(c.skill + (state.education > 70 ? 4 : 2));
409:     c.satisfaction = clamp((c.satisfaction || 70) + (c.remote ? 1 : -1) - (state.stress > 70 ? 3 : 0));
410:     if (Math.random() < .3 && c.level < 10) { c.level++; c.salary = Math.round(c.salary * 1.08); addEvent('↗', 'Uma promoção chegou', `Seu salário agora é ${money(c.salary)} por mês.`, 'blue'); }
411:   }
412:   if (state.age >= 45 && Math.random() < .08 && !state.healthConditions.includes('pressão alta')) state.healthConditions.push('pressão alta');
413:   const event = yearlyEvent(); addEvent(event.icon, event.title, event.text, event.cls);
414:   if (wasInPrison) addEvent('⚖', 'Um ano difícil', state.prisonYears ? `Você cumpriu mais um ano de prisão. Restam ${state.prisonYears}.` : 'Você cumpriu sua pena e está tentando reconstruir a vida.', 'pink');
415:   state.history.push({ year: state.year, age: state.age, money: Math.round(state.money), career: c.title });
416:   const reachedLimit = state.age >= 105;
417:   const healthFailure = state.health <= 0;
418:   const lateLifeRisk = state.age >= 92 && Math.random() < .15;
419:   if (healthFailure || lateLifeRisk || reachedLimit) {
420:     state.dead = true;
421:     state.deathCause = healthFailure ? 'complicações de saúde' : reachedLimit ? 'idade avançada' : 'fim natural da jornada';
422:     addEvent('☾', 'O fim de uma jornada', `Sua história terminou por ${state.deathCause}, mas seu legado permanece.`, 'pink');
423:   }
