438:     ['youtube', 'tiktok', 'instagram', 'twitter'].forEach(key => { state.socialMedia[key].followers = Math.max(0, Math.round(state.socialMedia[key].followers * annualGrowth)); state.socialMedia[key].engagement = clamp(state.socialMedia[key].engagement + (state.socialMedia.controversy > 40 ? -3 : 1)); });
439:     state.socialMedia.controversy = clamp(state.socialMedia.controversy - 5);
440:     state.fame = clamp(state.fame + (totalFollowers > 10000 ? 3 : 1) - (state.socialMedia.controversy > 40 ? 2 : 0));
441:   }
442:   if (state.fame >= 60 && c.employed) { const brandIncome = Math.round(state.fame * 18); state.money += brandIncome; addEvent('★', 'A fama trouxe renda', `Marcas pagaram ${money(brandIncome)} por sua visibilidade.`, 'blue'); }
443:   state.energy = clamp(state.energy + (state.age < 30 ? 2 : -3));
444:   state.needs.sleep = clamp(state.needs.sleep - 5 + (state.energy > 60 ? 4 : 0));
445:   state.needs.social = clamp(state.needs.social - 3 + (state.relationships.length ? 2 : 0));
