410: function advanceYear() {
411:   if (state.dead) return toast('Esta vida chegou ao fim. Comece uma nova história.');
412:   state.age++; state.year++; const c = state.career;
413:   const wasInPrison = state.prisonYears > 0;
414:   if (wasInPrison) state.prisonYears = Math.max(0, state.prisonYears - 1);
415:   const income = c.employed && state.prisonYears === 0 && !wasInPrison ? c.salary * 12 : 0;
416:   const expenses = Math.round(state.finances.expenses * 12 * (1 + state.age / 500));
417:   const investmentReturn = state.finances.investments * ((Math.random() * .12) - .03);
418:   state.finances.investments = Math.max(0, state.finances.investments + investmentReturn);
419:   const balanceBeforeDebt = state.money + income - expenses;
420:   const deficit = Math.max(0, -balanceBeforeDebt);
421:   state.money = Math.max(0, balanceBeforeDebt);
422:   if (deficit) { state.finances.debt += deficit; state.credit = clamp(state.credit - 35, 0, 900); }
423:   else { state.finances.debt = Math.max(0, state.finances.debt - Math.min(state.finances.debt, income * .05)); state.credit = clamp(state.credit + 8, 0, 900); }
424:   const agePenalty = state.age > 70 ? 2.5 : state.age > 45 ? 1 : .25;
425:   state.health = clamp(state.health - agePenalty - (state.stress > 70 ? 1.5 : 0));
426:   changeStat('happiness', deficit ? -6 : state.money > expenses ? 1 : -1);
427:   state.stress = clamp(state.stress + 3 + (deficit ? 5 : 0) - (state.trait === 'espiritual' ? 2 : 0));
428:   const addictionKeys = ['alcohol', 'drugs', 'gambling'];
429:   addictionKeys.forEach(key => {
430:     const risk = safePercent(state.addictions[key]);
431:     if (state.addictions.recovery) state.addictions[key] = clamp(risk - 8);
432:     else if (risk >= 35) { state.addictions[key] = clamp(risk + 4); state.stress = clamp(state.stress + 4); state.health = clamp(state.health - 2); }
433:   });
434:   if (state.addictions.recovery && addictionKeys.every(key => state.addictions[key] < 15)) state.addictions.recovery = false;
435:   if (state.stress >= 75 && !state.mental.diagnoses.includes('ansiedade')) { state.mental.diagnoses.push('ansiedade'); addEvent('☾', 'Seu corpo pediu atenção', 'O estresse persistente foi reconhecido como ansiedade; acompanhamento pode ajudar.', 'pink'); }
436:   if (state.happiness <= 30 && !state.mental.diagnoses.includes('depressão')) { state.mental.diagnoses.push('depressão'); addEvent('☾', 'Você recebeu um alerta de cuidado', 'Sua felicidade baixa merece acolhimento, apoio e acompanhamento profissional.', 'pink'); }
437:   if (state.mental.treated) { state.stress = clamp(state.stress - 5); state.happiness = clamp(state.happiness + 2); }
438:   if (state.identity.discovered) { state.stress = clamp(state.stress - 1); state.happiness = clamp(state.happiness + 1); }
439:   const totalFollowers = ['youtube', 'tiktok', 'instagram', 'twitter'].reduce((sum, key) => sum + state.socialMedia[key].followers, 0);
440:   if (totalFollowers > 0) {
441:     const annualGrowth = state.socialMedia.controversy > 40 ? .92 : 1 + Math.min(.25, state.fame / 500);
442:     ['youtube', 'tiktok', 'instagram', 'twitter'].forEach(key => { state.socialMedia[key].followers = Math.max(0, Math.round(state.socialMedia[key].followers * annualGrowth)); state.socialMedia[key].engagement = clamp(state.socialMedia[key].engagement + (state.socialMedia.controversy > 40 ? -3 : 1)); });
443:     state.socialMedia.controversy = clamp(state.socialMedia.controversy - 5);
444:     state.fame = clamp(state.fame + (totalFollowers > 10000 ? 3 : 1) - (state.socialMedia.controversy > 40 ? 2 : 0));
445:   }
446:   if (state.fame >= 60 && c.employed) { const brandIncome = Math.round(state.fame * 18); state.money += brandIncome; addEvent('★', 'A fama trouxe renda', `Marcas pagaram ${money(brandIncome)} por sua visibilidade.`, 'blue'); }
447:   state.energy = clamp(state.energy + (state.age < 30 ? 2 : -3));
448:   state.needs.sleep = clamp(state.needs.sleep - 5 + (state.energy > 60 ? 4 : 0));
449:   state.needs.social = clamp(state.needs.social - 3 + (state.relationships.length ? 2 : 0));
450:   state.needs.nutrition = clamp(state.needs.nutrition - 2 + (state.money > expenses ? 3 : 0));
451:   state.needs.purpose = clamp(state.needs.purpose + (c.employed ? 2 : -4));
