453:   if (neglectedNeeds) { state.stress = clamp(state.stress + neglectedNeeds * 4); state.health = clamp(state.health - neglectedNeeds * 2); }
454:   state.relationships.forEach(person => { person.affinity = clamp(person.affinity - (Math.random() < .4 ? 2 : 0)); });
455:   state.children.forEach(child => { child.age = safeNumber(child.age) + 1; });
456:   if (c.employed) {
