  const rental = $('#landlordList'); if (rental) rental.innerHTML = state.landlord.properties.length ? state.landlord.properties.map(property => { const tenant = state.landlord.tenants.find(t => t.propertyId === property.id); return `<div class="goal"><span class="goal-icon">⌂</span><div><b>${escapeHTML(property.name)}</b><small>${tenant ? `${escapeHTML(tenant.name)} · ${money(tenant.rent)}${tenant.overdue ? ' · aluguel atrasado' : ''}` : 'sem inquilino'}</small></div></div>`; }).join('') : '<div class="system-copy">Nenhum imóvel para alugar.</div>';
  $$('[data-sell-collectible]').forEach(button => button.onclick = () => sellCollectible(Number(button.dataset.sellCollectible)));
}
