324: function educationMenu(courseId = null) {
325:   if (state.dead) return toast('Esta vida chegou ao fim.');
326:   const entries = Object.entries(educationCourses);
327:   if (courseId && educationCourses[courseId]) entries.sort(([id]) => id === courseId ? -1 : 1);
328:   const choices = entries.map(([id, course]) => ({
329:     label: `${course.name} · ${money(course.cost)}`,
330:     detail: `${course.energy} energia; aumenta educação e ${course.skill}. Desbloqueia ${course.unlock}.`,
331:     action: () => runAction(`course-${id}`, () => {
332:       if (!requireAge(6)) return;
333:       const current = state.educationCourse;
334:       if ((state.educationHistory || []).some(item => item.id === id)) return toast(`${course.name} já está no seu histórico de formação.`);
335:       if (current && current.id !== id && current.progress < 100) return toast(`Conclua ${current.name} antes de trocar de curso.`);
336:       if (!requireResources(course.cost, course.energy)) return;
337:       const progress = current?.id === id ? current.progress : 0;
338:       const next = clamp(progress + course.gain * (state.trait === 'ambicioso' ? 1.2 : 1));
339:       state.educationCourse = { id, name: course.name, module: next >= 70 ? 'projeto final' : next >= 35 ? 'prática' : 'fundamentos', progress: Math.round(next) };
340:       state.education = clamp(state.education + course.gain);
341:       state.skills[course.skill] = clamp((state.skills[course.skill] || 50) + 3);
342:       if (next >= 100) { state.educationHistory.push({ id, name: course.name, year: state.year }); state.educationCourse = null; addEvent('⌘', `${course.name} concluído`, `Seu certificado desbloqueou ${course.unlock}.`, 'blue'); }
343:       else addEvent('⌘', `Você avançou em ${course.name}`, `O módulo de ${state.educationCourse.module} está ${Math.round(next)}% concluído.`);
344:     })
345:   }));
346:   openChoiceModal('Escolha sua formação', 'Cursos têm custo, ritmo e portas diferentes. Você pode estudar novamente para avançar no mesmo curso.', choices);
